base64 -d > "$PROJ/окна_авито/01_база_знаний/скрипты_ответов.md" <<'B64EOF'

B64EOF
mkdir -p "$(dirname "$PROJ/окна_авито/02_память/журнал_изменений.md")"
base64 -d > "$PROJ/окна_авито/02_память/журнал_изменений.md" <<'B64EOF'

B64EOF
mkdir -p "$(dirname "$PROJ/окна_авито/02_память/история_проекта.md")"
base64 -d > "$PROJ/окна_авито/02_память/история_проекта.md" <<'B64EOF'

B64EOF
mkdir -p "$(dirname "$PROJ/окна_авито/05_чаты_авито/README.md")"
base64 -d > "$PROJ/окна_авито/05_чаты_авито/README.md" <<'B64EOF'

B64EOF
mkdir -p "$(dirname "$PROJ/окна_авито/05_чаты_авито/_chats_raw.json")"
base64 -d > "$PROJ/окна_авито/05_чаты_авито/_chats_raw.json" <<'B64EOF'

B64EOF
mkdir -p "$(dirname "$PROJ/окна_авито/05_чаты_авито/_conversations.json")"
base64 -d > "$PROJ/окна_авито/05_чаты_авито/_conversations.json" <<'B64EOF'

B64EOF
mkdir -p "$(dirname "$PROJ/окна_авито/05_чаты_авито/диалоги_читаемый.md")"
base64 -d > "$PROJ/окна_авито/05_чаты_авито/диалоги_читаемый.md" <<'B64EOF'

B64EOF
mkdir -p "$(dirname "$PROJ/окна_авито/06_анализы/анализ_30_сообщений.md")"
base64 -d > "$PROJ/окна_авито/06_анализы/анализ_30_сообщений.md" <<'B64EOF'

B64EOF
