base64 -d > "$PROJ/окна_авито/06_анализы/аудит_объявлений_2026-10-25.md" <<'B64EOF'

B64EOF
mkdir -p "$(dirname "$PROJ/окна_авито/08_дашборды/ссылки.md")"
base64 -d > "$PROJ/окна_авито/08_дашборды/ссылки.md" <<'B64EOF'

B64EOF
mkdir -p "$(dirname "$PROJ/окна_авито/09_telegram/боты_и_каналы.md")"
base64 -d > "$PROJ/окна_авито/09_telegram/боты_и_каналы.md" <<'B64EOF'

B64EOF
mkdir -p "$(dirname "$PROJ/окна_авито/10_ссылки/все_ссылки.md")"
base64 -d > "$PROJ/окна_авито/10_ссылки/все_ссылки.md" <<'B64EOF'

B64EOF
mkdir -p "$(dirname "$PROJ/skills/business-project-workspace/SKILL.md")"
base64 -d > "$PROJ/skills/business-project-workspace/SKILL.md" <<'B64EOF'

B64EOF
mkdir -p "$(dirname "$PROJ/skills/avito-market-analysis/SKILL.md")"
base64 -d > "$PROJ/skills/avito-market-analysis/SKILL.md" <<'B64EOF'

B64EOF
mkdir -p "$(dirname "$PROJ/skills/hermes-vps-hostinger/SKILL.md")"
base64 -d > "$PROJ/skills/hermes-vps-hostinger/SKILL.md" <<'B64EOF'

B64EOF

# копия скиллов в Hermes на VPS
if [ -d /opt/data/skills ]; then
  for d in $PROJ/skills/*; do
    [ -d "$d" ] && cp -r "$d" /opt/data/skills/ 2>/dev/null || true
  done
  chown -R 10000:10000 /opt/data/skills 2>/dev/null || true
fi
mkdir -p /opt/projects/digest
base64 -d > /opt/projects/digest/digest.py <<'B64EOF'

B64EOF

# конфиг для отчёта (тот же, что у бота)
cp -f /opt/hermes-chat-agent/config.json /opt/projects/digest/config.json 2>/dev/null || true

# cron: каждый день 06:00 UTC = 09:00 МСК
cat > /etc/cron.d/okna-digest <<'CRONEOF'
SHELL=/bin/bash
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
0 6 * * * root set -a; . /etc/default/hermes-chat-agent; set +a; /usr/bin/python3 /opt/projects/digest/digest.py >> /var/log/okna-digest.log 2>&1
CRONEOF
chmod 644 /etc/cron.d/okna-digest

mkdir -p /opt/projects/_реестр
echo '{"projects":[{"name":"окна_авито","path":"/opt/projects/окна_авито","status":"active","owner_chat":"1915169528"}]}' > /opt/projects/_реестр/projects.json

echo "=== УСТАНОВЛЕНО ==="
ls -1 /opt/projects
echo "--- проект ---"
ls -1 /opt/projects/окна_авито | head -20
echo "--- тест отчёта ---"
set -a; . /etc/default/hermes-chat-agent; set +a
/usr/bin/python3 /opt/projects/digest/digest.py | head -20
echo "=== ГОТОВО ==="
